def sortare(a):
    if len(a) < 2:
        return a
    m = len(a) // 2
    x, y = sortare(a[:m]), sortare(a[m:])
    i = j = 0
    b = []
    while i < len(x) and j < len(y):
        if x[i] <= y[j]:
            b.append(x[i])
            i += 1
        else:
            b.append(y[j])
            j += 1
    return b + x[i:] + y[j:]
print(*sortare(list(map(int, input().split()))))

def maxim(a, st, dr):
    if st == dr:
        return a[st]
    m = (st + dr) // 2
    return max(maxim(a, st, m), maxim(a, m + 1, dr))
