n, S = map(int, input().split())
a = [tuple(map(int, input().split())) for _ in range(n)]
def bkt(i, ramas):
    if i == n:
        return int(ramas == 0)
    v, stoc = a[i]
    return sum(bkt(i + 1, ramas - k * v) for k in range(min(stoc, ramas // v) + 1))
print(bkt(0, S))
